// 05 Section 10/14's automation risk boundary, applied to Tag-for-Action's human-to-AI path:
// 'auto-execute reversible/internal, human-gate external-send/billing/irreversible' - 'Chat-invoked
// requests are a new trigger type, not a new permission,' meaning this uses the SAME classification
// every other AI-employee action in this repo already follows, not a separate rule invented for
// chat. The action vocabulary itself isn't specified anywhere in the source docs - this is a
// reasonable, conservative starting set (flagged, not silently assumed complete): anything not
// explicitly recognized as reversible is treated as gated, erring toward the human-approval side
// rather than accidentally auto-executing something irreversible.
const REVERSIBLE_ACTIONS = ['summarize', 'summarise', 'research', 'draft-note', 'draft-email', 'draft-summary'];

const action = ($('Tag for Action webhook').item.json.body.action || '').toLowerCase().trim();
const reversible = REVERSIBLE_ACTIONS.includes(action);

return [{
  json: {
    reversible,
    reason: reversible
      ? `"${action}" is a read-only/reversible request - auto-executes immediately.`
      : `"${action}" is not in the recognized reversible set - treated as external-send/billing/irreversible by default, routed to human approval.`,
  },
}];

const body = $input.first().json;
const textBlock = (body.content || []).find((b) => b.type === 'text');
if (!textBlock) throw new Error('Claude response had no text content block.');
return [{ json: { aiResponseText: textBlock.text } }];
